      ["'I'll go home' (on foot) =", ["Budu jít domů.", "Pojedu domů.", "Půjdu domů.", "Půjdu doma."], 2, "jít does not take budu: on foot, 'I'll go' is půjdu, and home as a destination is domů."],
      ["'Will you be here tomorrow?' (to a stranger) =", ["Budeš tady zítra?", "Budete tady zítra?", "Bude tady zítra?", "Budete být tady zítra?"], 1, "budete for a stranger, and budete alone already means 'will be'."]
